-- Use the guarded, row-locking run source for query evidence persistence.
-- Preserve payload, replay and target claim validation from the active writer.
SET LOCAL ROLE sqlobserver_migrator;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '5min';
SET LOCAL TIME ZONE 'UTC';

CREATE OR REPLACE FUNCTION control.commit_query_performance_collection_run(p_run_id uuid, p_instance_id uuid, p_target_revision bigint, p_completion_digest bytea, p_window_start timestamptz, p_window_end timestamptz, p_source events.query_performance_source, p_source_state text, p_coverage text, p_freshness boolean, p_truncated boolean, p_fence_token bigint, p_payload jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, control, events, telemetry AS $fn$
DECLARE existing_digest bytea; selected_work_key text; selected_owner uuid; selected_revision bigint; item jsonb; status_item jsonb; db integer; query_id bytea; plan_id bytea; plan_key bytea; start_at timestamptz; end_at timestamptz; observed_at timestamptz; semantics_value text; executions_value bigint; cpu_value bigint; cumulative_executions bigint; cumulative_cpu bigint; duration_value bigint; reads_value bigint; writes_value bigint; rows_value bigint; prior_executions bigint; prior_cpu bigint; reset_value boolean;
BEGIN
 IF p_run_id IS NULL OR p_instance_id IS NULL OR p_target_revision <= 0 OR p_fence_token <= 0 OR octet_length(p_completion_digest) <> 32 OR p_window_end <= p_window_start OR p_window_end-p_window_start > interval '7 days' OR jsonb_typeof(p_payload) <> 'object' OR jsonb_typeof(p_payload->'observations') <> 'array' OR jsonb_array_length(p_payload->'observations') > 20000 OR jsonb_typeof(p_payload->'databaseStatuses') <> 'array' OR jsonb_array_length(p_payload->'databaseStatuses') > 256 OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'databaseStatuses') value GROUP BY value->>'databaseId' HAVING count(*) > 1) OR octet_length(convert_to(p_payload::text,'UTF8')) > 8388608 OR p_source_state NOT IN ('read_write','read_only','disabled','unsupported','permission_denied','read_failure','timed_out','mixed','unavailable') OR p_coverage NOT IN ('complete','truncated','unavailable','no_activity') OR (p_payload ? 'targetStatus' AND (jsonb_typeof(p_payload->'targetStatus') <> 'object' OR p_payload->'targetStatus'->>'status' IS NULL OR p_payload->'targetStatus'->>'reason' IS NULL)) THEN RAISE EXCEPTION 'query performance commit preflight failed' USING ERRCODE='22023'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value GROUP BY value->>'databaseId' HAVING count(DISTINCT value->>'queryFingerprint') > 2000) OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value GROUP BY value->>'databaseId',value->>'queryFingerprint' HAVING count(*) > 20000 OR count(DISTINCT NULLIF(value->>'planFingerprint','')) > 50) OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE jsonb_typeof(value) <> 'object' OR EXISTS (SELECT 1 FROM jsonb_object_keys(value) key WHERE key NOT IN ('databaseId','queryFingerprint','planFingerprint','source','sourceState','semantics','intervalStartUtc','intervalEndUtc','observedAtUtc','cpuMs','durationMs','executions','logicalReads','writes','rows','coverage','fresh','truncated'))) OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE value->>'databaseId' !~ '^[0-9]+$') OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE value->>'queryFingerprint' IS NULL OR value->>'queryFingerprint' !~ '^[0-9a-fA-F]{64}$') OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE value->>'source' NOT IN ('query_store','plan_cache') OR value->>'sourceState' IS NULL OR value->>'sourceState' NOT IN ('read_write','read_only','disabled','unsupported','permission_denied','read_failure','timed_out') OR (p_source <> 'mixed' AND value->>'source' IS DISTINCT FROM p_source::text) OR ((value->>'source')='query_store' AND value->>'semantics' <> 'query_store_interval') OR ((value->>'source')='plan_cache' AND value->>'semantics' = 'query_store_interval')) OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE value->>'planFingerprint' IS NOT NULL AND value->>'planFingerprint' <> '' AND value->>'planFingerprint' !~ '^[0-9a-fA-F]{64}$') THEN RAISE EXCEPTION 'query performance payload shape or cap invalid' USING ERRCODE='22023'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE (value->>'intervalStartUtc')::timestamptz < p_window_start OR (value->>'intervalEndUtc')::timestamptz > p_window_end) THEN RAISE EXCEPTION 'query performance observation is outside requested window' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_payload->'observations') > 0 AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'databaseStatuses') status_value WHERE status_value->>'databaseId'=value->>'databaseId')) THEN RAISE EXCEPTION 'query performance observation status is missing' USING ERRCODE='22023'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') observation_value JOIN LATERAL (SELECT value AS status_value FROM jsonb_array_elements(p_payload->'databaseStatuses') value WHERE value->>'databaseId'=observation_value->>'databaseId') status_row ON true WHERE (status_row.status_value->>'status'='query_store_rows' AND (observation_value->>'source')<>'query_store') OR (status_row.status_value->>'status'='plan_cache_rows' AND (observation_value->>'source')<>'plan_cache') OR status_row.status_value->>'status' NOT IN ('query_store_rows','plan_cache_rows')) THEN RAISE EXCEPTION 'query performance observation source and status mismatch' USING ERRCODE='22023'; END IF;
 IF NOT control.query_performance_target_claim(p_instance_id) THEN RAISE EXCEPTION 'query performance target claim missing' USING ERRCODE='42501'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'databaseStatuses') status_value WHERE
      ((status_value->>'status') IN ('query_store_empty','query_store_disabled','query_store_unsupported','query_store_permission_denied','query_store_read_failure','query_store_timed_out','plan_cache_empty','plan_cache_permission_denied','plan_cache_read_failure','plan_cache_timed_out','output_capped') AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') observation_value WHERE observation_value->>'databaseId'=status_value->>'databaseId'))
   OR ((status_value->>'status')='query_store_rows' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') observation_value WHERE observation_value->>'databaseId'=status_value->>'databaseId' AND observation_value->>'source'='query_store'))
   OR ((status_value->>'status')='plan_cache_rows' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') observation_value WHERE observation_value->>'databaseId'=status_value->>'databaseId' AND observation_value->>'source'='plan_cache')))
 THEN RAISE EXCEPTION 'query performance status and observation source mismatch' USING ERRCODE='22023'; END IF;
 SELECT work_key,owner_execution_id,target_revision INTO selected_work_key,selected_owner,selected_revision FROM telemetry.lock_collection_run_runtime(p_run_id) AS run WHERE run.instance_id=p_instance_id AND run.collector_id='queries.performance';
 IF selected_work_key IS NULL OR selected_owner IS NULL OR selected_revision <> p_target_revision THEN RAISE EXCEPTION 'query performance active run or target revision missing' USING ERRCODE='55000'; END IF;
 PERFORM control.assert_worker_lease(selected_work_key,selected_owner,p_fence_token);
 IF NOT EXISTS (SELECT 1 FROM control.collector_schedule WHERE instance_id=p_instance_id AND collector_id='queries.performance' AND active_run_id=p_run_id AND target_revision=p_target_revision) THEN RAISE EXCEPTION 'query performance schedule fence missing' USING ERRCODE='55000'; END IF;
 SELECT completion_digest INTO existing_digest FROM events.query_performance_run WHERE collection_run_id=p_run_id FOR SHARE;
 IF existing_digest IS NOT NULL THEN IF existing_digest <> p_completion_digest THEN RAISE EXCEPTION 'query performance replay digest mismatch' USING ERRCODE='40001'; END IF; RETURN true; END IF;
 INSERT INTO events.query_performance_run(collection_run_id,instance_id,target_revision,window_start,window_end,source,source_state,coverage,freshness,truncated,target_status,target_reason,completion_digest) VALUES(p_run_id,p_instance_id,p_target_revision,p_window_start,p_window_end,p_source,p_source_state,p_coverage,p_freshness,p_truncated,p_payload->'targetStatus'->>'status',p_payload->'targetStatus'->>'reason',p_completion_digest);
 FOR status_item IN SELECT value FROM jsonb_array_elements(p_payload->'databaseStatuses') LOOP
   IF jsonb_typeof(status_item)<>'object' OR status_item->>'databaseId' !~ '^[0-9]+$' OR status_item->>'status' NOT IN ('query_store_empty','query_store_rows','query_store_disabled','query_store_unsupported','query_store_permission_denied','query_store_read_failure','query_store_timed_out','plan_cache_rows','plan_cache_empty','plan_cache_permission_denied','plan_cache_read_failure','plan_cache_timed_out','output_capped') OR status_item->>'fallbackAttempted' IS NULL OR ((status_item->>'status') LIKE 'query_store_%' AND (status_item->>'fallbackAttempted')::boolean) OR ((status_item->>'status') LIKE 'plan_cache_%' AND NOT (status_item->>'fallbackAttempted')::boolean) OR status_item->>'sourceState' IS NULL OR status_item->>'sourceState' NOT IN ('read_write','read_only','disabled','unsupported','permission_denied','read_failure','timed_out') OR ((status_item->>'status') IN ('query_store_rows','query_store_empty') AND status_item->>'sourceState' NOT IN ('read_write','read_only')) OR status_item->>'lossKind' NOT IN ('none','source_row_limit','response_byte_limit','output_validation_failure','ingestion_rejection','duplicate_overlap') OR status_item->>'reason' IS NULL OR status_item->>'truncated' IS NULL OR status_item->>'sourceRowsRead' IS NULL OR status_item->>'responseBytes' IS NULL OR ((status_item->>'status') NOT IN ('query_store_rows','plan_cache_rows','output_capped') AND (status_item->>'lossKind' IN ('source_row_limit','response_byte_limit') OR (status_item->>'truncated')::boolean AND status_item->>'lossKind' = 'none')) OR NOT ((status_item->>'status'='query_store_empty' AND status_item->>'reason'='query_store_empty') OR (status_item->>'status'='query_store_rows' AND status_item->>'reason' IN ('query_store_read','query_store_empty')) OR (status_item->>'status'='query_store_disabled' AND status_item->>'reason'='query_store_disabled') OR (status_item->>'status'='query_store_unsupported' AND status_item->>'reason' IN ('query_store_unsupported','query_store_probe_missing')) OR (status_item->>'status'='query_store_permission_denied' AND status_item->>'reason'='query_store_permission_denied') OR (status_item->>'status'='query_store_read_failure' AND status_item->>'reason'='query_store_read_failure') OR (status_item->>'status'='query_store_timed_out' AND status_item->>'reason'='query_store_timeout') OR (status_item->>'status'='plan_cache_rows' AND status_item->>'reason'='plan_cache_fallback') OR (status_item->>'status'='plan_cache_empty' AND status_item->>'reason'='plan_cache_empty') OR (status_item->>'status'='plan_cache_permission_denied' AND status_item->>'reason'='plan_cache_permission_denied') OR (status_item->>'status'='plan_cache_read_failure' AND status_item->>'reason'='plan_cache_read_failure') OR (status_item->>'status'='plan_cache_timed_out' AND status_item->>'reason'='plan_cache_timeout') OR (status_item->>'status'='output_capped' AND status_item->>'reason'='output_capped')) OR octet_length(status_item->>'reason')>128 OR (status_item->>'sourceRowsRead')::integer NOT BETWEEN 0 AND 2001 OR (status_item->>'responseBytes')::integer NOT BETWEEN 0 AND 8388608 THEN RAISE EXCEPTION 'query performance database status shape invalid' USING ERRCODE='22023'; END IF;
   IF COALESCE((status_item->>'minimumLostItems')::integer,0) NOT BETWEEN 0 AND 20000 OR COALESCE((status_item->>'minimumLostBytes')::integer,0) NOT BETWEEN 0 AND 8388608 OR status_item->>'lossKind'='none' AND (COALESCE((status_item->>'minimumLostItems')::integer,0)<>0 OR COALESCE((status_item->>'minimumLostBytes')::integer,0)<>0 OR COALESCE((status_item->>'lossCountIsExact')::boolean,true)<>true) OR status_item->>'lossKind'<>'none' AND COALESCE((status_item->>'minimumLostItems')::integer,0)=0 AND COALESCE((status_item->>'minimumLostBytes')::integer,0)=0 AND COALESCE((status_item->>'lossCountIsExact')::boolean,true)=true THEN RAISE EXCEPTION 'query performance database status loss detail invalid' USING ERRCODE='22023'; END IF;
   INSERT INTO events.query_performance_database_status(collection_run_id,instance_id,database_id,status,source_state,reason,fallback_attempted,truncated,loss_kind,source_rows_read,response_bytes,minimum_lost_items,loss_count_is_exact,minimum_lost_bytes) VALUES(p_run_id,p_instance_id,(status_item->>'databaseId')::integer,status_item->>'status',status_item->>'sourceState',status_item->>'reason',(status_item->>'fallbackAttempted')::boolean,(status_item->>'truncated')::boolean,status_item->>'lossKind',(status_item->>'sourceRowsRead')::integer,(status_item->>'responseBytes')::integer,COALESCE((status_item->>'minimumLostItems')::integer,0),COALESCE((status_item->>'lossCountIsExact')::boolean,true),COALESCE((status_item->>'minimumLostBytes')::integer,0));
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_payload->'observations') LOOP
   IF jsonb_typeof(item) <> 'object' OR item->>'databaseId' !~ '^[0-9]+$' OR (item->>'queryFingerprint') !~ '^[0-9a-fA-F]{64}$' OR (item->>'intervalStartUtc') IS NULL OR (item->>'intervalEndUtc') IS NULL THEN RAISE EXCEPTION 'query performance observation shape invalid' USING ERRCODE='22023'; END IF;
   db := (item->>'databaseId')::integer; query_id := decode(item->>'queryFingerprint','hex'); plan_id := CASE WHEN item->>'planFingerprint' IS NULL OR item->>'planFingerprint'='' THEN NULL ELSE decode(item->>'planFingerprint','hex') END; start_at := (item->>'intervalStartUtc')::timestamptz; end_at := (item->>'intervalEndUtc')::timestamptz; observed_at := COALESCE((item->>'observedAtUtc')::timestamptz,clock_timestamp()); semantics_value := COALESCE(item->>'semantics','query_store_interval'); executions_value := NULLIF(item->>'executions','')::bigint; cpu_value := NULLIF(item->>'cpuMs','')::bigint; duration_value := NULLIF(item->>'durationMs','')::bigint; reads_value := NULLIF(item->>'logicalReads','')::bigint; writes_value := NULLIF(item->>'writes','')::bigint; rows_value := NULLIF(item->>'rows','')::bigint;
   IF db NOT BETWEEN 1 AND 32767 OR octet_length(query_id)<>32 OR (plan_id IS NOT NULL AND octet_length(plan_id)<>32) OR end_at<=start_at OR end_at-start_at>interval '7 days' OR semantics_value NOT IN ('query_store_interval','plan_cache_cumulative','plan_cache_delta','plan_cache_baseline','reset') THEN RAISE EXCEPTION 'query performance observation bounds invalid' USING ERRCODE='22023'; END IF;
   INSERT INTO events.query_performance_query(collection_run_id,instance_id,database_id,query_fingerprint) VALUES(p_run_id,p_instance_id,db,query_id) ON CONFLICT DO NOTHING;
   IF plan_id IS NOT NULL THEN INSERT INTO events.query_performance_plan(collection_run_id,database_id,query_fingerprint,plan_fingerprint) VALUES(p_run_id,db,query_id,plan_id) ON CONFLICT DO NOTHING; END IF;
   IF (item->>'source')='plan_cache' AND semantics_value IN ('plan_cache_cumulative','plan_cache_delta','plan_cache_baseline','reset') THEN
     cumulative_executions := executions_value;
     cumulative_cpu := cpu_value;
     plan_key := coalesce(plan_id,decode(repeat('00',32),'hex'));
     SELECT baseline.cumulative_executions,baseline.cumulative_cpu_ms
     INTO prior_executions,prior_cpu
     FROM events.query_performance_cache_baseline AS baseline
     WHERE baseline.instance_id=p_instance_id
       AND baseline.database_id=db
       AND baseline.query_fingerprint=query_id
       AND baseline.plan_fingerprint=plan_key
     FOR UPDATE;
     reset_value := cumulative_executions IS NULL OR cumulative_cpu IS NULL OR prior_executions IS NULL OR prior_cpu IS NULL OR cumulative_executions < prior_executions OR cumulative_cpu < prior_cpu;
     IF reset_value THEN
       semantics_value := CASE WHEN prior_executions IS NULL OR prior_cpu IS NULL THEN 'plan_cache_baseline' ELSE 'reset' END;
     ELSE
       -- Keep the persisted representation cumulative until every supported
       -- counter (duration, reads, writes and rows) has a matching baseline.
       -- A partial delta would mislabel the remaining cumulative fields.
       executions_value := cumulative_executions;
       cpu_value := cumulative_cpu;
       semantics_value := 'plan_cache_cumulative';
     END IF;
     INSERT INTO events.query_performance_cache_baseline(instance_id,database_id,query_fingerprint,plan_fingerprint,cumulative_executions,cumulative_cpu_ms,last_seen_at,reset_generation) VALUES(p_instance_id,db,query_id,plan_key,COALESCE(cumulative_executions,0),COALESCE(cumulative_cpu,0),observed_at,CASE WHEN reset_value AND prior_executions IS NOT NULL THEN 1 ELSE 0 END) ON CONFLICT(instance_id,database_id,query_fingerprint,plan_fingerprint) DO UPDATE SET cumulative_executions=EXCLUDED.cumulative_executions,cumulative_cpu_ms=EXCLUDED.cumulative_cpu_ms,last_seen_at=EXCLUDED.last_seen_at,reset_generation=events.query_performance_cache_baseline.reset_generation+CASE WHEN reset_value THEN 1 ELSE 0 END;
   END IF;
   INSERT INTO events.query_performance_observation(collection_run_id,database_id,query_fingerprint,plan_fingerprint,observation_key,source,source_state,interval_start,interval_end,observed_at,semantics,cpu_ms,duration_ms,execution_count,logical_reads,writes,rows_processed) VALUES(p_run_id,db,query_id,plan_id,decode(substr(md5(coalesce(encode(plan_id,'hex'),'none')||(item->>'source')||start_at::text||end_at::text||observed_at::text),1,32),'hex'),(item->>'source')::events.query_performance_source,coalesce(item->>'sourceState',p_source_state),start_at,end_at,observed_at,semantics_value,cpu_value,duration_value,executions_value,reads_value,writes_value,rows_value) ON CONFLICT DO NOTHING;
 END LOOP;
 -- The canonical control.commit_collection_run call owns schedule, circuit, outcome, and accounting finalization.
 RETURN true;
END; $fn$;
